/***************************************************************************************************** 
 *
 * Given two words word1 and word2, find the minimum number of operations required to convert word1 to 
 * word2.
 * 
 * You have the following 3 operations permitted on a word:
 * 
 * 	Insert a character
 * 	Delete a character
 * 	Replace a character
 * 
 * Example 1:
 * 
 * Input: word1 = "horse", word2 = "ros"
 * Output: 3
 * Explanation: 
 * horse -> rorse (replace 'h' with 'r')
 * rorse -> rose (remove 'r')
 * rose -> ros (remove 'e')
 * 
 * Example 2:
 * 
 * Input: word1 = "intention", word2 = "execution"
 * Output: 5
 * Explanation: 
 * intention -> inention (remove 't')
 * inention -> enention (replace 'i' with 'e')
 * enention -> exention (replace 'n' with 'x')
 * exention -> exection (replace 'n' with 'c')
 * exection -> execution (insert 'u')
 * 
 ******************************************************************************************************/

class Solution {
    public int minDistance(String word1, String word2) {
        if (word1 == null || word2 == null) {
            return 0;
        }

        var m = word1.length();
        var n = word2.length();
        var dp = new int[m + 1][n + 1];

        for (var i = 0; i <= m; i++) {
            dp[i][0] = i;
        }
        for (var j = 1; j <= n; j++) {
            dp[0][j] = j;
        }

        for (var i = 1; i <= m; i++) {
            for (var j = 1; j <= n; j++) {
                if (word1.charAt(i - 1) == word2.charAt(j - 1)) {
                    dp[i][j] = Math.min(
                        Math.min(dp[i - 1][j], dp[i][j - 1]) + 1, dp[i - 1][j - 1]);
                } else {
                    dp[i][j] = Math.min(
                        Math.min(dp[i - 1][j], dp[i][j - 1]), dp[i - 1][j - 1]) + 1;
                }
            }
        }

        return dp[m][n];
    }
}

class Solution {
public:
    int minDistance(string word1, string word2) {
        int len1 = word1.size(), len2 = word2.size();
        vector<vector<int>> dp(2, vector<int>(len1 + 1, 0));
        for (int i = 0; i <= len1; i++) {
            dp[0][i] = i;
        }
        for (int i = 1; i <= len2; i++) {
            for (int j = 0; j <= len1; j++) {
                if (j == 0) {
                    dp[i % 2][j] = i;
                }
                else if (word1[j - 1] == word2[i - 1]) {
                    dp[i % 2][j] = dp[(i - 1) % 2][j - 1];
                }
                else {
                    dp[i % 2][j] = 1 + min({dp[(i-1) % 2][j], dp[i % 2][j - 1], dp[(i - 1) % 2][j - 1]});
                }
            }
        }
        return dp[len2 % 2][len1];
    }
};

class Solution(object):
    def minDistance(self, word1, word2):
        """
        :type word1: str
        :type word2: str
        :rtype: int
        """
        self.w1 = word1
        self.w2 = word2
        self.table = {}
        return self.recurse(0,0)

    def recurse(self, i1, i2):
        if (i1, i2) in self.table:
            return self.table[(i1, i2)]
        if i1==len(self.w1):
            result = len(self.w2)-i2
        elif i2==len(self.w2):
            result = len(self.w1)-i1
        elif self.w1[i1]==self.w2[i2]:
            result = self.recurse(i1+1, i2+1)
        else:
            # delete a char from w1
            d1 = self.recurse(i1+1, i2)
            d2 = self.recurse(i1, i2+1)
            d3 = self.recurse(i1+1, i2+1)
            result = min(d1, d2, d3)+1
        self.table[(i1, i2)]=result
        return result

